//! Minimal re-implementation of the ColorSpace pieces used by test11.
//!
//! Behavior was inferred black-box from the reference binary:
//! - `RGB` stores its channels as 32-bit floats (`float` in C++).
//! - `ColorConverter::invert` maps each channel `c` to `1 - c`.
//! - `ColorConverter::grayscale` computes Rec.709 luma
//!   `0.2126*r + 0.7152*g + 0.0722*b` and replicates it on all channels.

/// RGB color with `float` (f32) channels, mirroring `ColorSpace::RGB`.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Rgb {
    pub r: f32,
    pub g: f32,
    pub b: f32,
}

impl Rgb {
    pub fn new(r: f32, g: f32, b: f32) -> Self {
        Rgb { r, g, b }
    }
}

/// Mirrors the static helpers of `ColorSpace::ColorConverter`.
pub struct ColorConverter;

impl ColorConverter {
    /// Per-channel inversion: `1 - c`.
    pub fn invert(color: Rgb) -> Rgb {
        Rgb::new(1.0 - color.r, 1.0 - color.g, 1.0 - color.b)
    }

    /// Rec.709 luma replicated across all three channels.
    pub fn grayscale(color: Rgb) -> Rgb {
        let luma = 0.2126 * color.r + 0.7152 * color.g + 0.0722 * color.b;
        Rgb::new(luma, luma, luma)
    }
}

//! Formatting helpers that reproduce C++ `std::ostream << float` output.
//!
//! The default `std::cout` formatting for floating point is `%g` with a
//! precision of 6 significant digits: fixed notation when the decimal
//! exponent `X` of the rounded value satisfies `-4 <= X < 6`, scientific
//! notation (`d.dddddde+XX`) otherwise, with trailing zeros stripped.

/// Format an f32 exactly the way `std::cout << value` would.
pub fn format_cout_float(value: f32) -> String {
    format_g(value as f64, 6)
}

/// `%g` formatting with `precision` significant digits (no `#` flag).
fn format_g(x: f64, precision: i32) -> String {
    if x.is_nan() {
        return if x.is_sign_negative() { "-nan".into() } else { "nan".into() };
    }
    if x.is_infinite() {
        return if x > 0.0 { "inf".into() } else { "-inf".into() };
    }
    if x == 0.0 {
        return if x.is_sign_negative() { "-0".into() } else { "0".into() };
    }

    // Round to `precision` significant digits and read off the decimal
    // exponent of the *rounded* value (this correctly handles carry-over
    // such as 999999.5 -> 1e+06).
    let sci = format!("{:.*e}", (precision - 1) as usize, x);
    let epos = sci.find('e').unwrap();
    let exp: i32 = sci[epos + 1..].parse().unwrap();

    if exp < -4 || exp >= precision {
        // Scientific notation: strip trailing zeros from the mantissa,
        // exponent printed with a sign and at least two digits.
        let mantissa = strip_trailing_zeros(&sci[..epos]);
        format!("{}e{}{:02}", mantissa, if exp < 0 { '-' } else { '+' }, exp.abs())
    } else {
        // Fixed notation with precision - 1 - exp digits after the point.
        let digits = (precision - 1 - exp) as usize;
        let fixed = format!("{:.*}", digits, x);
        strip_trailing_zeros(&fixed)
    }
}

/// Remove trailing fraction zeros (and a dangling decimal point).
fn strip_trailing_zeros(s: &str) -> String {
    if !s.contains('.') {
        return s.to_string();
    }
    let trimmed = s.trim_end_matches('0').trim_end_matches('.');
    trimmed.to_string()
}

