/// Emulates C++ `std::stof` (via glibc `strtof`):
/// - parses the longest valid float prefix: leading whitespace, optional
///   sign, decimal (`d[.d][e[+-]d]`), hex (`0xh[.h][p[+-]d]`), inf, nan;
/// - throws `std::invalid_argument` (aborts) when no conversion exists;
/// - throws `std::out_of_range` (aborts) when the value overflows f32 or
///   underflows into the subnormal/zero range.
fn stof(s: &str) -> f32 {
    let trimmed = s.trim_start();
    let lower = trimmed.to_ascii_lowercase();
    let rest = lower
        .strip_prefix('+')
        .or_else(|| lower.strip_prefix('-'))
        .unwrap_or(&lower);
    let sign_len = lower.len() - rest.len();
    let negative = lower.starts_with('-');

    // inf / nan literals — never range-checked.
    if rest.starts_with("inf") || rest.starts_with("nan") {
        let len = sign_len
            + rest
                .find(|c: char| !(c.is_ascii_alphanumeric() || c == '(' || c == ')'))
                .unwrap_or(rest.len());
        return match trimmed[..len].parse::<f32>() {
            Ok(v) => v,
            Err(_) => abort_stof("std::invalid_argument"),
        };
    }

    let bytes = rest.as_bytes();
    let value: f64;
